Store.script:
class Component extends DCLogic {
shared(k, d) { try { var S = parent.SONNA_STORE; return S ? S.get(k, d) : d; } catch (e) { return d; } }
state = {
view: 'home', catId: '', itemId: '', qty: 1, q: '', menuOpen: false, banner: 0, logged: true, wallet: null,
input: '', tryCode: '', paid: false, paidInfo: null,
used: { BANMOI: true }, orders: null, open: {}, sold: this.shared('sold', {}),
topTab: 'bank', amount: 100000, topMsg: '', telco: 'Viettel', face: 100000, serial: '', pin: '', cardMsg: false, cardErr: false
};
mount() {
setInterval(() => {
const a = document.activeElement;
if (this.state.view === 'home' && !(a && /INPUT|TEXTAREA|SELECT/.test(a.tagName)) && !matchMedia('(prefers-reduced-motion: reduce)').matches) this.setState({ banner: (this.state.banner || 0) + 1 });
}, 5000);
}
renderVals() {
const st = this.state;
const fmt = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + '₫';
const baseWallet = this.props.wallet !== undefined && this.props.wallet !== null ? Number(this.props.wallet) : 470000;
const wallet = st.wallet === null ? baseWallet : st.wallet;
const norm = (s) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[đĐ]/g, 'd').toLowerCase();

const CATS = [
{ id: 'ra', name: 'Reroll DBL Android', kind: 'pack', col: '#5B1F7A' },
{ id: 'ri', name: 'Reroll DBL iOS', kind: 'pack', col: '#2F6FD6' },
{ id: 'ca', name: 'Character + Chrono Android', kind: 'single', col: '#C2273D' },
{ id: 'ci', name: 'Character + Chrono iOS', kind: 'single', col: '#0E8F8F' },
{ id: 'tm', name: 'Team Meta', kind: 'single', col: '#D9780F' }
];
let PACKS = [
{ id: 'ra50', cat: 'ra', title: 'DBL 50K-55K APK', stock: 12, sold: 390, price: 10000, gift: true },
{ id: 'ra60', cat: 'ra', title: 'DBL 60K-65K APK', stock: 14, sold: 258, price: 20000, gift: false },
{ id: 'ra70', cat: 'ra', title: 'DBL 70K-75K APK', stock: 19, sold: 69, price: 45000, gift: false },
{ id: 'ra80', cat: 'ra', title: 'DBL 80K-85K APK', stock: 5, sold: 62, price: 80000, gift: false },
{ id: 'ra90', cat: 'ra', title: 'DBL 90K-95K APK', stock: 0, sold: 48, price: 100000, gift: false },
{ id: 'ri50', cat: 'ri', title: 'DBL 50K-55K iOS', stock: 26, sold: 251, price: 18000, gift: true },
{ id: 'ri60', cat: 'ri', title: 'DBL 60K-65K iOS', stock: 41, sold: 162, price: 30000, gift: false },
{ id: 'ri70', cat: 'ri', title: 'DBL 70K-75K iOS', stock: 21, sold: 66, price: 60000, gift: false }
];
let SINGLES = [
{ id: 'CA-1042', cat: 'ca', level: 118, crystal: '12.400', chars: 46, price: 1250000 },
{ id: 'CA-1039', cat: 'ca', level: 142, crystal: '21.050', chars: 68, price: 3400000 },
{ id: 'CA-1037', cat: 'ca', level: 74, crystal: '2.300', chars: 19, price: 320000 },
{ id: 'CI-1041', cat: 'ci', level: 96, crystal: '5.800', chars: 31, price: 690000 },
{ id: 'CI-1034', cat: 'ci', level: 131, crystal: '15.900', chars: 55, price: 2150000 },
{ id: 'TM-0008', cat: 'tm', level: 110, crystal: '8.200', chars: 40, price: 1800000 },
{ id: 'TM-0011', cat: 'tm', level: 125, crystal: '9.900', chars: 52, price: 2600000 }
];
const CATALOG = this.shared('catalog', null);
const ACC = this.shared('acc', {});
if (CATALOG) {
const MAPC = { 'reroll-android': 'ra', 'reroll-ios': 'ri', 'char-android': 'ca', 'char-ios': 'ci', 'team-meta': 'tm' };
PACKS = []; SINGLES = [];
CATALOG.subs.forEach((sb) => { if (!MAPC[sb.cat] || !sb.title) return;
PACKS.push({ id: sb.id, cat: MAPC[sb.cat], title: sb.title, stock: CATALOG.accts.filter((a) => a.sub === sb.id && a.status === 'Đang bán').length, sold: CATALOG.accts.filter((a) => a.sub === sb.id && a.status === 'Đã bán').length, price: sb.price, gift: !!sb.gift, pics: (ACC.subPics || {})[sb.id] || [] }); });
CATALOG.accts.forEach((a) => { if (['char-android', 'char-ios', 'team-meta'].indexOf(a.cat) < 0 || a.status !== 'Đang bán') return;
SINGLES.push({ id: a.id, cat: MAPC[a.cat], level: a.level || '–', crystal: a.chrono || '–', chars: a.chars || '–', price: a.price, pics: (ACC.accPics || {})[a.id] || [] }); });
}
const catById = (id) => CATS.find((c) => c.id === id);
const catOrder = this.shared('catOrder', null);
const itemOrder = this.shared('itemOrder', {});
const CATS_ORD = CATS.slice().sort((a, b) => { const ia = catOrder ? catOrder.indexOf(a.id) : -1, ib = catOrder ? catOrder.indexOf(b.id) : -1; return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib); });
const rankIn = (it) => { const o = itemOrder[it.cat]; const r = o ? o.indexOf(it.id) : -1; return r < 0 ? 999 : r; };
const items = PACKS.map((p) => ({ ...p, isPack: true })).concat(SINGLES.map((s) => ({ ...s, isPack: false, title: 'Acc #' + s.id, stock: 1 }))).map((it, i) => ({ ...it, stock: Math.max(0, it.stock - (st.sold[it.id] || 0)), _i: i })).sort((a, b) => (rankIn(a) - rankIn(b)) || (a._i - b._i));
const colOf = (it) => catById(it.cat).col;
const go = (patch) => this.setState({ menuOpen: false, ...patch });

const cardOf = (it) => {
const out = it.stock === 0;
return {
title: it.title, pic: (it.pics || [])[0] || '', hasPic: !!(it.pics && it.pics.length), price: fmt(it.price), ribbon: !!it.gift, tag: it.isPack ? (it.cat === 'ra' || it.cat === 'ca' ? 'Android' : 'iOS') : (it.cat === 'tm' ? 'Team Meta' : (it.cat === 'ca' ? 'Android' : 'iOS')),
line: it.isPack ? 'Còn lại: ' + it.stock + ' | Đã bán: ' + (it.sold + (st.sold[it.id] || 0)) : 'Cấp ' + it.level + ' · ' + it.crystal + ' tinh thể · ' + it.chars + ' nhân vật',
bg: colOf(it), soldOut: out, btn: out ? 'Hết hàng' : 'Mua ngay', btnBg: out ? '#D6D2E2' : '#FF8A1F', btnFg: out ? '#5A5470' : '#1A1206', cursor: out ? 'not-allowed' : 'pointer',
pick: () => go({ view: 'detail', catId: it.cat, itemId: it.id, qty: 1, input: '', tryCode: '', paid: false, paidInfo: null })
};
};

// menu
const menuDefs = [
{ id: 'home', label: 'Trang chủ', pick: () => go({ view: 'home' }) },
{ id: 'cats', label: 'Danh mục ▾', pick: () => this.setState({ menuOpen: !st.menuOpen }) },
{ id: 'topup', label: 'Nạp tiền', pick: () => go({ view: 'topup', topMsg: '' }) },
{ id: 'history', label: 'Lịch sử', pick: () => go({ view: 'history' }) },
{ id: 'guide', label: 'Hướng dẫn', pick: () => go({ view: 'guide' }) }
];
const curMenu = st.view === 'cat' || st.view === 'detail' ? 'cats' : st.view;
const menu = menuDefs.map((m) => ({ label: m.label, pick: m.pick, bg: m.id === curMenu ? '#5B1F7A' : 'transparent', cur: m.id === curMenu ? 'page' : 'false' }));
const catMenu = CATS_ORD.map((c) => ({ id: c.id, name: c.name, pick: () => go({ view: 'home' }) }));
const catTiles = CATS_ORD.map((c) => ({ id: c.id, name: c.name, col: c.col, pick: () => go({ view: 'home' }) }));

// banners (từ trang Nội dung website nếu có)
const DEFAULT_B = [
{ id: 1, kind: 'main', title: 'ACC REROLL UY TÍN, GIAO TỰ ĐỘNG', link: '', on: true, img: '', kicker: 'SONNA · ACC DRAGON BALL LEGENDS', sub: 'Thanh toán bằng ví, nhận TK|MK ngay sau khi trừ tiền.', bg: 'linear-gradient(120deg,#2D0A3F,#5B1F7A 60%,#8A3FB0)' },
{ id: 2, kind: 'main', title: 'NẠP VÍ THƯỞNG THÊM 5%', link: '', on: true, img: '', kicker: 'KHUYẾN MÃI NẠP', sub: 'Nạp 100.000₫ nhận 105.000₫. Nạp ngân hàng hoặc thẻ cào.', bg: 'linear-gradient(120deg,#102A56,#2F6FD6 70%,#58A0F0)' },
{ id: 3, kind: 'sub', title: 'Mua 1 tặng 1', link: '', on: true, img: '', kicker: '', sub: 'Một số gói reroll được tặng thêm 1 acc cùng loại, giao tự động ngay khi thanh toán. Mua nhiều acc vẫn chỉ tặng 1.', bg: '#fff' }
];
const bAll = this.shared('banners', DEFAULT_B).filter((x) => x.on);
const decorate = (x) => ({ title: x.title, kicker: x.kicker || 'SONNA', sub: x.sub || '', bg: x.bg || 'linear-gradient(120deg,#2D0A3F,#5B1F7A 60%,#8A3FB0)', img: x.img || '', hasImg: !!x.img, noImg: !x.img });
const mains = bAll.filter((x) => x.kind === 'main').map(decorate);
const subs = bAll.filter((x) => x.kind === 'sub').map(decorate);
const banner = mains.length ? mains[st.banner % mains.length] : decorate({ title: '' });
const sub = subs.length ? subs[0] : decorate({ title: '' });
const dots = mains.length > 1 ? mains.map((b, i) => ({ n: i + 1, w: i === st.banner % mains.length ? '28px' : '12px', op: i === st.banner % mains.length ? 1 : 0.6, pick: () => this.setState({ banner: i }) })) : [];

// chữ chạy + liên hệ
const MQ = this.shared('marq', { on: true, speed: 'mid', tone: 'orange', text: 'Nạp ví hôm nay nhận thêm 5% giá trị nạp\nAcc được admin đăng nhập kiểm tra trước khi đăng bán\nHỗ trợ qua Zalo trong giờ làm việc' });
const mqLines = String(MQ.text || '').split('\n').map((x) => x.trim()).filter((x) => x !== '');
const mqTone = { orange: ['#FF8A1F', '#1A1206'], blue: ['#52C7FF', '#0A1620'], dark: ['#1F2538', '#EAEFFA'] }[MQ.tone] || ['#FF8A1F', '#1A1206'];
const mqBase = { slow: 14, mid: 9, fast: 5 }[MQ.speed] || 9;
const mqText = mqLines.join('   •   ');
const mqDur = Math.max(mqBase, Math.round(mqText.length / 8 * (mqBase / 9))) + 's';
const CT = this.shared('contact', { phone: { v: '[SỐ ĐIỆN THOẠI]', on: true }, zalo: { v: '[SỐ ZALO]', on: true }, fanpage: { v: '[LINK FANPAGE]', on: true }, zgroup: { v: '[LINK NHÓM ZALO]', on: true }, email: { v: '[EMAIL HỖ TRỢ]', on: false }, youtube: { v: '[LINK KÊNH YOUTUBE]', on: false } });
const CT_L = { phone: 'Hotline', zalo: 'Zalo', fanpage: 'Fanpage', zgroup: 'Nhóm Zalo', email: 'Email', youtube: 'YouTube' };
const contactLines = Object.keys(CT_L).filter((k) => CT[k] && CT[k].on).map((k) => ({ k: CT_L[k], v: CT[k].v }));
const hours = this.shared('hours', '08:00 - 22:00 hằng ngày');
if (CT.phone && CT.phone.on || CT.zalo && CT.zalo.on) contactLines.push({ k: 'Giờ hỗ trợ', v: hours });

// home sections with search
const qq = norm((st.q || '').trim());
const match = (it) => qq === '' || norm(it.title).indexOf(qq) >= 0 || norm(catById(it.cat).name).indexOf(qq) >= 0 || norm(it.id).indexOf(qq) >= 0;
const sections = CATS_ORD.map((c) => { const cards = items.filter((it) => it.cat === c.id && match(it)).map(cardOf); return { id: c.id, name: c.name, count: cards.length, cards }; }).filter((s) => s.cards.length > 0);

// category view
const cat = catById(st.catId) || CATS[0];

// detail
const it = items.find((x) => x.id === st.itemId) || items[0];
const qty = it.isPack ? Math.max(1, Math.min(st.qty, it.stock || 1)) : 1;
const price = it.price * qty;
let CODES = {
GIAM10: { kind: 'pct', val: 10, min: 300000, cap: 50000, scope: 'all', until: '31/10/2026', expired: false },
BANMOI: { kind: 'amt', val: 20000, min: 100000, cap: 0, scope: 'all', until: 'Không hết hạn', expired: false },
REROLLIOS: { kind: 'pct', val: 5, min: 0, cap: 0, scope: 'ri', scopeLabel: 'Acc Reroll iOS', until: '20/12/2026', expired: false },
TETVUI: { kind: 'amt', val: 50000, min: 500000, cap: 0, scope: 'all', until: '30/09/2026', expired: true }
};
const SC = { 'Tất cả danh mục': 'all', 'Acc Reroll iOS': 'ri', 'Acc Reroll Android': 'ra', 'Acc Character + Chrono iOS': 'ci', 'Acc Character + Chrono Android': 'ca', 'Team Meta': 'tm' };
const parseD = (x) => { const m = /^(\d+)\/(\d+)\/(\d+)$/.exec(x || ''); return m ? new Date(+m[3], +m[2] - 1, +m[1], 23, 59, 59) : null; };
const shCodes = this.shared('codes', null);
if (shCodes) { CODES = {}; shCodes.forEach((c) => { const dd = parseD(c.until); CODES[c.code] = { kind: c.kind, val: c.val, min: c.min, cap: c.cap, scope: SC[c.scope] || 'all', scopeLabel: c.scope, until: c.until, expired: c.status === 'expired' || !!(dd && dd < new Date()), paused: c.status === 'paused', full: c.limit > 0 && c.used >= c.limit }; }); }
const evaluate = (raw) => {
const code = (raw || '').trim().toUpperCase();
if (code === '') return null;
const c = CODES[code];
if (!c) return { ok: false, msg: 'Mã “' + code + '” không tồn tại. Kiểm tra lại chính tả.' };
if (c.expired) return { ok: false, msg: 'Mã ' + code + ' đã hết hạn ngày ' + c.until + '.' };
if (c.paused) return { ok: false, msg: 'Mã ' + code + ' đang tạm dừng.' };
if (c.full) return { ok: false, msg: 'Mã ' + code + ' đã hết lượt dùng.' };
if (st.used[code]) return { ok: false, msg: 'Tài khoản của bạn đã dùng mã ' + code + ' rồi. Mỗi mã chỉ dùng 1 lần cho mỗi tài khoản.' };
if (c.scope !== 'all' && c.scope !== it.cat) return { ok: false, msg: 'Mã ' + code + ' chỉ áp dụng cho ' + c.scopeLabel + ', không dùng cho đơn này.' };
if (price < c.min) return { ok: false, msg: 'Đơn cần từ ' + fmt(c.min) + ' để dùng mã ' + code + '.' };
let d = c.kind === 'pct' ? Math.round(price * c.val / 100) : c.val;
if (c.kind === 'pct' && c.cap > 0 && d > c.cap) d = c.cap;
if (d > price) d = price;
return { ok: true, code, discount: d, offer: c.kind === 'pct' ? 'Giảm ' + c.val + '%' + (c.cap > 0 ? ' (tối đa ' + fmt(c.cap) + ')' : '') : 'Giảm ' + fmt(c.val), until: c.until };
};
const res = evaluate(st.tryCode);
const applied = !!(res && res.ok);
const discount = applied ? res.discount : 0;
const total = price - discount;
const enough = wallet >= total;
const remain = wallet - total;
const canPay = st.logged && enough && it.stock > 0;
const sumRows = [{ k: it.isPack ? 'Giá ' + fmt(it.price) + ' × ' + qty : 'Giá acc', v: fmt(price), col: '#1B1530' }];
if (applied) sumRows.push({ k: 'Giảm giá (' + res.code + ')', v: '-' + fmt(discount), col: '#14744E' });
if (it.gift) sumRows.push({ k: 'Quà tặng', v: '1 acc cùng loại', col: '#8A4B00' });

const d = {
pics: (it.pics || []).map((src) => ({ src })), hasPics: !!(it.pics && it.pics.length),
title: it.title, bg: colOf(it), priceText: fmt(it.price) + (it.isPack ? ' / acc' : ''), isPack: it.isPack, gift: !!it.gift, stock: it.stock,
info: it.isPack
? [{ k: 'Danh mục', v: cat.name }, { k: 'Còn lại', v: it.stock + ' acc' }, { k: 'Đã bán', v: String(it.sold) }, { k: 'Liên kết', v: 'Bandai Namco ID' }]
: [{ k: 'Danh mục', v: cat.name }, { k: 'Cấp độ', v: String(it.level) }, { k: 'Tinh thể', v: it.crystal }, { k: 'Số nhân vật', v: String(it.chars) }, { k: 'Liên kết', v: 'Bandai Namco ID' }]
};

const mk = (id, n) => id.toLowerCase() + '_' + String(1000 + n) + '|Sn@' + (7000 + n * 13);
const buildAccs = (itm, q) => {
const list = [];
for (let i = 0; i < q; i++) list.push({ line: mk(itm.id, st.orders ? st.orders.length * 7 + i + 1 : i + 1), tag: 'Acc mua', col: '#14744E' });
if (itm.gift) list.push({ line: mk('km' + itm.cat, (st.orders ? st.orders.length : 0) + 41), tag: 'Quà tặng', col: '#8A4B00' });
return list;
};
const doneRows = st.paidInfo ? [
{ k: 'Mã đơn', v: st.paidInfo.code },
{ k: 'Sản phẩm', v: st.paidInfo.title },
{ k: 'Mã giảm giá', v: st.paidInfo.coupon },
{ k: 'Đã trừ từ ví', v: fmt(st.paidInfo.total) },
{ k: 'Số dư ví còn lại', v: fmt(st.paidInfo.remain) }
] : [];

// orders
const baseOrders = [
{ code: 'DH-20841', title: 'Acc #CA-1042', time: '16/10/2026 09:41', total: 1250000, accs: [{ line: 'ca1042_demo|Sn@7001', tag: 'Acc mua', col: '#14744E' }] },
{ code: 'DH-20790', title: 'DBL 50K-55K APK × 1', time: '12/10/2026 19:05', total: 10000, accs: [{ line: 'ra50_1007|Sn@7091', tag: 'Acc mua', col: '#14744E' }, { line: 'kmra_1041|Sn@7533', tag: 'Quà tặng', col: '#8A4B00' }] }
];
const allOrders = (st.orders || []).concat(baseOrders);
const orders = allOrders.map((o) => ({
code: o.code, title: o.title, time: o.time, total: fmt(o.total), accs: o.accs,
open: !!st.open[o.code], toggleLabel: st.open[o.code] ? 'Ẩn thông tin acc' : 'Xem thông tin acc',
toggle: () => this.setState({ open: { ...st.open, [o.code]: !st.open[o.code] } })
}));

// topup
const amount = st.amount;
const TP = this.shared('topup', { enabled: true, pct: '5', min: '0', cap: '' });
const tpPct = parseFloat(String(TP.pct).replace(',', '.')) || 0;
const tpMin = parseInt(String(TP.min).replace(/\D/g, ''), 10) || 0;
const tpCap = parseInt(String(TP.cap).replace(/\D/g, ''), 10) || 0;
let bonus = (TP.enabled !== false && amount >= tpMin) ? Math.round(amount * tpPct / 100) : 0;
if (tpCap > 0 && bonus > tpCap) bonus = tpCap;
const bonusLabel = 'Nạp ' + fmt(amount) + (bonus > 0 ? ' · thưởng nạp ' + tpPct + '%' : ' · chưa có thưởng nạp');
const chips = [50000, 100000, 200000, 500000].map((a) => ({ label: fmt(a), line: a === amount ? '#2D0A3F' : '#D6D2E2', pick: () => this.setState({ amount: a, topMsg: '' }) }));
const topTabs = [{ id: 'bank', label: 'Chuyển khoản ngân hàng' }, { id: 'card', label: 'Thẻ cào' }].map((t) => ({ label: t.label, pick: () => this.setState({ topTab: t.id }), line: t.id === st.topTab ? '#FF8A1F' : 'transparent', fg: t.id === st.topTab ? '#2D0A3F' : '#5A5470' }));
const cardReceive = fmt(Math.round(st.face * 0.8));

const steps = [
{ n: '01', t: 'Nạp ví', d: 'Nạp ngân hàng hoặc thẻ cào. Nạp bao nhiêu nhận bấy nhiêu, có thưởng nạp theo chương trình.' },
{ n: '02', t: 'Chọn acc', d: 'Chọn danh mục, gói hoặc acc, rồi nhập mã giảm giá nếu có (mỗi đơn 1 mã).' },
{ n: '03', t: 'Thanh toán bằng ví', d: 'Hệ thống trừ ví và giao TK|MK ngay, kèm acc quà tặng nếu gói có khuyến mãi.' },
{ n: '04', t: 'Đổi mật khẩu', d: 'Đổi thông tin liên kết ngay khi nhận và liên hệ hỗ trợ nếu có sự cố trong thời gian bảo hành.' }
];

return {
logged: st.logged, loggedOut: !st.logged, walletText: fmt(wallet),
login: () => this.setState({ logged: true }), logout: () => this.setState({ logged: false }),
goHome: () => go({ view: 'home' }), goHistory: () => go({ view: 'history' }), goGuide: () => go({ view: 'guide' }),
goTopupBank: () => go({ view: 'topup', topTab: 'bank', topMsg: '' }), goTopupCard: () => go({ view: 'topup', topTab: 'card', cardMsg: false }),
noop: (e) => { if (e && e.preventDefault) e.preventDefault(); },
q: st.q, onQuery: (e) => this.setState({ q: e.target.value, view: st.view === 'home' ? 'home' : 'home' }),
menu, menuOpen: st.menuOpen, catMenu, catTiles, banner, sub, dots, hasMain: mains.length > 0, hasSub: subs.length > 0,
marqShow: MQ.on && mqLines.length > 0, marqBg: mqTone[0], marqFg: mqTone[1], marqDur: mqDur, marqLine: mqText, contactLines,
isHome: st.view === 'home', isDetail: st.view === 'detail', isTopup: st.view === 'topup', isHistory: st.view === 'history', isGuide: st.view === 'guide',
sections, noResult: sections.length === 0,
catName: cat.name,
d, qty, paid: st.paid, notPaid: !st.paid, doneRows, delivered: st.paidInfo ? st.paidInfo.accs : [],
qtyUp: () => this.setState({ qty: Math.min(qty + 1, it.stock || 1), tryCode: '', input: '' }),
qtyDown: () => this.setState({ qty: Math.max(1, qty - 1), tryCode: '', input: '' }),
input: st.input, onInput: (e) => this.setState({ input: e.target.value }),
onApply: () => this.setState({ tryCode: this.state.input }),
onRemove: () => this.setState({ tryCode: '', input: '' }),
noApplied: !applied, showErr: !!(res && !res.ok), errText: res && !res.ok ? res.msg : '',
showApplied: applied, code: applied ? res.code : '', offerText: applied ? res.offer : '', untilText: applied ? res.until : '',
sumRows, totalText: fmt(total),
