const effBuy = buyOptions.some((o) => o.t === st.rBuySel) ? st.rBuySel : (buyOptions[0] ? buyOptions[0].t : '');
const effGive = giftOptions.some((o) => o.t === st.rGiveSel) ? st.rGiveSel : (giftOptions[0] ? giftOptions[0].t : '');
const onSaveRule = () => {
const b = num(st.rBuy), g2 = num(st.rGive);
if (!b || !g2) return this.flash('Nhập số lượng mua và số lượng tặng từ 1 trở lên.', true);
if (!effBuy || !effGive || effBuy.indexOf('(chưa') === 0 || effGive.indexOf('(chưa') === 0) return this.flash('Chọn mục acc bán và mục kho tặng đã có tiêu đề.', true);
if (st.rFrom && st.rTo && st.rTo < st.rFrom) return this.flash('Ngày kết thúc phải sau ngày bắt đầu.', true);
if (rulesAll.some((r) => r.buySub === effBuy && r.buy === b && r.giveSub === effGive && r.give === g2)) return this.flash('Quy tắc này đã có.', true);
this.setState({ rulesData: rulesAll.concat([{ id: 'r' + Date.now(), buy: b, buySub: effBuy, give: g2, giveSub: effGive, from: st.rFrom, until: st.rTo, paused: false }]), rBuy: '1', rGive: '1', rFrom: '', rTo: '' });
this.flash('Đã lưu quy tắc tặng acc.');
};

const onExport = () => {
const esc = (v) => '"' + String(v === undefined || v === null ? '' : v).replace(/"/g, '""') + '"';
const head = ['Mã acc', 'Tài khoản', 'Danh mục', 'Thông tin', 'Giá bán', 'Giá nhập', 'Trạng thái'];
const lines = [head.map(esc).join(',')].concat(rows.map((r) => [r.id, r.tk, r.catLabel, r.sub, r.price, r.cost, r.status].map(esc).join(',')));
try {
const blob = new Blob(['\ufeff' + lines.join('\r\n')], { type: 'text/csv;charset=utf-8' });
const url = URL.createObjectURL(blob); const link = document.createElement('a');
link.href = url; link.download = 'danh-sach-acc.csv'; document.body.appendChild(link); link.click(); document.body.removeChild(link);
setTimeout(() => URL.revokeObjectURL(url), 1000);
this.flash('Đã xuất ' + rows.length + ' acc ra file CSV (không gồm mật khẩu).');
} catch (e) { this.flash('Trình duyệt không cho phép tải file này.', true); }
};


const catalog = {
subs: ['reroll-ios', 'reroll-android'].flatMap((c) => getSubs(c).map((x) => ({ id: x.id, cat: c, title: val(x.id, 't', x.title), price: num(val(x.id, 'p', x.price)), gift: activeRules.some((r) => r.buy === 1 && r.give === 1 && r.buySub === val(x.id, 't', x.title)) }))),
accts: merged.filter((r) => !r.del && r.cat !== 'promo').map((r) => ({ id: r.id, cat: r.cat, sub: r.sub, status: r.status, price: num(r.price), level: r.level, chrono: r.chrono, chars: r.chars }))
};
const catJs = JSON.stringify(catalog);
if (catJs !== this._lastCat) { this._lastCat = catJs; this.saveShared('catalog', catalog); }
const onAccImgs = (e) => { const fl = e.target.files; if (!fl || !fl.length) return; this.compress(fl, (imgs) => this.setState({ accImgs: (this.state.accImgs || []).concat(imgs) })); };
const accImgs = (st.accImgs || []).map((src, idx) => ({
src,
del: () => { const arr = [...st.accImgs]; arr.splice(idx, 1); this.setState({ accImgs: arr }); }
}));
return {
toastShow: st.toast !== '', toast: st.toast, toastCol: st.toastBad ? '#FF6B7A' : ok, closeToast: () => this.setState({ toast: '' }),
cfShow: !!st.cf, cf: st.cf ? { title: st.cf.title, text: st.cf.text, btn: st.cf.btn } : { title: '', text: '', btn: '' }, cfYes, cfNo: () => this.setState({ cf: null }),
edShow: showEdit, ed, noRules: rules.length === 0, onExport,
rBuy: st.rBuy, rGive: st.rGive, rFrom: st.rFrom, rTo: st.rTo, effBuy, effGive, onSaveRule,
onRBuy: (e) => this.setState({ rBuy: e.target.value }), onRGive: (e) => this.setState({ rGive: e.target.value }),
onRBuySel: (e) => this.setState({ rBuySel: e.target.value }), onRGiveSel: (e) => this.setState({ rGiveSel: e.target.value }),
onRFrom: (e) => this.setState({ rFrom: e.target.value }), onRTo: (e) => this.setState({ rTo: e.target.value }),
msgShow: st.msg !== '', msg: st.msg, selCount: picked.length,
bulkHide: () => patch({ status: 'Đã ẩn', col: off }),
bulkShow: () => patch({ status: 'Đang bán', col: ok }),
bulkGift: () => patch({ cat: 'promo', status: 'Trong kho', col: ok, price: 'Không bán lẻ', sub: '' }),
bulkDel: () => { if (!picked.length) return this.flash('Chưa chọn acc nào.', true); askDelAcc(picked); },
toggleAll: () => this.setState({ selIds: allOn ? {} : Object.fromEntries(visIds.map((id) => [id, true])) }),
onBulkPost, onSinglePost: onSingle1(false), onDraft: onSingle1(true),
tk: st.tk, mk: st.mk, price: st.price, cost: st.cost, subSel: effSub,
onTk: (e) => this.setState({ tk: e.target.value, msg: '' }), onMk: (e) => this.setState({ mk: e.target.value, msg: '' }),
onPrice: (e) => this.setState({ price: e.target.value }), onCost: (e) => this.setState({ cost: e.target.value }),
onSubSel: (e) => this.setState({ subSel: e.target.value }),
accImgs,
hasImgs: accImgs.length > 0,
onAccImgs,
onLv: (e) => this.setState({ lv: e.target.value }), onCr: (e) => this.setState({ cr: e.target.value }), onCh: (e) => this.setState({ ch: e.target.value }), onTn: (e) => this.setState({ tn: e.target.value }),
lv: st.lv, cr: st.cr, ch: st.ch, tn: st.tn,
q: st.q,
onQuery: (e) => this.setState({ q: e.target.value }),
res,
nav, tabs, rows, f, bulk, subs, rules, buyOptions, giftOptions, subOptions, showSubs,
subsTitle: isPromoCat ? 'Kho acc tặng theo mục' : 'Mục con · ' + current.label,
subsHint: isPromoCat ? 'Đặt tiêu đề kho khớp với mục con của acc bán để chương trình tặng đúng loại.' : 'Tự đặt tiêu đề, giá và khuyến mãi cho từng mục con. Bấm "Xem acc" để lọc bảng bên dưới.',
colPrice: isPromoCat ? 'Hình thức' : 'Giá bán (₫)',
colStock: isPromoCat ? 'Acc trong kho' : 'Tồn kho',
colPromo: isPromoCat ? 'Đang dùng trong' : 'Khuyến mãi tặng',
addLabel: isPromoCat ? '+ Thêm mục kho tặng' : '+ Thêm mục con',
onAddSub: () => this.setState({ added: this.state.added.concat([{ id: 'n' + Date.now(), cat: this.state.cat }]) }),
formCat: st.formCat,
onFormCat: (e) => this.setState({ formCat: e.target.value, subSel: '', msg: '' }),
onSingle: () => this.setState({ mode: 'single' }),
onBulkMode: () => this.setState({ mode: 'bulk' }),
bulkText: st.bulk,
onBulk: (e) => this.setState({ bulk: e.target.value }),
footerText: 'Hiển thị ' + rows.length + ' acc'
};
}
}

