this.setState({ adjs: { ...st.adjs, [cur.id]: [e].concat(st.adjs[cur.id] || []) }, adjAmt: '', adjWhy: '', adjMsg: 'Đã cập nhật số dư (mô phỏng).' });
};
const sel = {
id: cur.id, name: cur.name, contact: cur.contact,
status: cur.isLocked ? 'Bị khóa' : 'Hoạt động',
