onAmt: (e) => this.setState({ adjAmt: e.target.value }), onWhy: (e) => this.setState({ adjWhy: e.target.value }),
onPlus: adjust(1), onMinus: adjust(-1),
nav, tabs, rows, sel,
noRows: rows.length === 0,
q: st.q,
onQuery: (e) => this.setState({ q: e.target.value }),
onLock: () => this.setState({ locks: { ...this.state.locks, [cur.id]: !cur.isLocked } }),
footerText: 'Hiển thị ' + rows.length + ' trên ' + DB.length + ' khách'
};
