AdminPromos.script:
class Component extends DCLogic {
shared(k, d) { try { var S = parent.SONNA_STORE; return S ? S.get(k, d) : d; } catch (e) { return d; } }
saveShared(k, v) { let r = false; try { r = parent.SONNA_STORE ? parent.SONNA_STORE.set(k, v) : false; } catch (e) {} if (!r) this._fail = true; return r; }
state = { tick: 0, fCode: '', fScope: 'Tất cả danh mục', fUntil: '', fLimit: '', fMsg: '', tab: 'all', kind: 'pct', val: '10', cap: '', min: '300000', order: '500000', stack: false };
renderVals() {
const on = '#FF8A1F', off = '#A3ACC4', ok = '#43D9A0';
const st = this.state;
const nav = [
{ label: 'Tổng quan', href: 'AdminDashboard.dc.html' },
{ label: 'Quản lý acc', href: 'AdminAccounts.dc.html' },
{ label: 'Đơn hàng', href: 'AdminOrders.dc.html' },
{ label: 'Thanh toán', href: 'AdminPayments.dc.html' },
{ label: 'Người dùng', href: 'AdminUsers.dc.html' },
{ label: 'Khuyến mãi', href: 'AdminPromos.dc.html', active: true },
{ label: 'Nội dung website', href: 'AdminContent.dc.html' },
{ label: 'Báo cáo', href: '#bao-cao' },
{ label: 'Phân quyền', href: 'AdminRoles.dc.html' },
{ label: 'Nhật ký hoạt động', href: '#nhat-ky' }
].map((n) => ({ ...n, bg: n.active ? '#1F2538' : 'transparent', fg: n.active ? on : off }));

const num = (s) => parseInt(String(s).replace(/\D/g, ''), 10) || 0;
const fmt = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + '₫';

const DEF = [
{ code: 'GIAM10', kind: 'pct', val: 10, min: 300000, cap: 50000, scope: 'Tất cả danh mục', used: 34, limit: 200, until: '31/10/2026', status: 'run' },
{ code: 'BANMOI', kind: 'amt', val: 20000, min: 100000, cap: 0, scope: 'Tất cả danh mục', used: 58, limit: 0, until: 'Không hết hạn', status: 'run' },
{ code: 'REROLLIOS', kind: 'pct', val: 5, min: 0, cap: 0, scope: 'Acc Reroll iOS', used: 12, limit: 100, until: '20/12/2026', status: 'paused' },
{ code: 'TETVUI', kind: 'amt', val: 50000, min: 500000, cap: 0, scope: 'Acc Character + Chrono', used: 100, limit: 100, until: '30/09/2026', status: 'expired' }
];
const CODES = this.shared('codes', null) || DEF;
const saveCodes = (L) => { this._fail = false; this.saveShared('codes', L); this.setState({ tick: this.state.tick + 1, fMsg: this._fail ? 'Không lưu được vào bộ nhớ trình duyệt.' : this.state.fMsg }); };
const META = {
run: { label: 'Đang chạy', col: ok, action: 'Tạm dừng' },
paused: { label: 'Tạm dừng', col: '#FFC24B', action: 'Bật lại' },
expired: { label: 'Hết hạn', col: off, action: 'Nhân bản' }
};
const count = (s) => CODES.filter((c) => c.status === s).length;
const tabs = [
{ id: 'all', label: 'Tất cả', count: CODES.length },
{ id: 'run', label: 'Đang chạy', count: count('run') },
{ id: 'paused', label: 'Tạm dừng', count: count('paused') },
{ id: 'expired', label: 'Hết hạn', count: count('expired') }
].map((t) => ({
...t,
pick: () => this.setState({ tab: t.id }),
line: t.id === st.tab ? on : 'transparent',
fg: t.id === st.tab ? '#EAEFFA' : off
}));
const rows = CODES.filter((c) => st.tab === 'all' || c.status === st.tab).map((c) => {
const offer = c.kind === 'pct' ? 'Giảm ' + c.val + '%' + (c.cap > 0 ? ' (tối đa ' + fmt(c.cap) + ')' : '') : 'Giảm ' + fmt(c.val);
const cond = (c.min > 0 ? 'Đơn từ ' + fmt(c.min) : 'Mọi giá trị đơn') + ' · ' + c.scope;
return {
code: c.code, offer, cond,
used: c.limit > 0 ? c.used + '/' + c.limit : c.used + ' (không giới hạn)',
until: c.until,
status: META[c.status].label, col: META[c.status].col, action: META[c.status].action,
act: () => {
let L;
if (c.status === 'run') L = CODES.map((x) => (x.code === c.code ? { ...x, status: 'paused' } : x));
else if (c.status === 'paused') L = CODES.map((x) => (x.code === c.code ? { ...x, status: 'run' } : x));
else L = CODES.concat([{ ...c, code: c.code + '_COPY', status: 'paused', used: 0, until: 'Không hết hạn' }]);
saveCodes(L);
}
};
});

const hub = [
{ title: 'Khuyến mãi nạp ví', status: 'Đang bật', col: ok, desc: 'Thưởng thêm % số tiền khách nạp. Ví dụ 5%: nạp 100.000₫ được thêm 5.000₫.', href: 'AdminPayments.dc.html', link: 'Mở cài đặt nạp ví' },
{ title: 'Tặng acc kèm', status: '1 quy tắc đang chạy', col: ok, desc: 'Mua acc ở một mục con thì được tặng acc lấy từ kho Acc Khuyến Mãi.', href: 'AdminAccounts.dc.html', link: 'Quản lý quy tắc tặng acc' },
{ title: 'Mã giảm giá', status: count('run') + ' mã đang chạy', col: ok, desc: 'Khách nhập mã khi thanh toán để được giảm giá đơn hàng.', href: '#ma-giam-gia', link: 'Tạo và quản lý mã bên dưới' }
];

const kindPct = st.kind === 'pct';
const amt = num(st.order);
const minOrder = num(st.min);
const cap = num(st.cap);
const v = kindPct ? (parseFloat(String(st.val).replace(',', '.')) || 0) : num(st.val);
let discount = 0;
let note = 'Giảm ' + (kindPct ? v + '% giá trị đơn.' : fmt(v) + ' cho mỗi đơn.');
if (amt < minOrder) {
note = 'Đơn chưa đạt mức tối thiểu ' + fmt(minOrder) + ' nên chưa được giảm.';
} else {
discount = kindPct ? Math.round(amt * v / 100) : v;
if (kindPct && cap > 0 && discount > cap) { discount = cap; note = 'Mức giảm đã chạm giới hạn tối đa.'; }
if (discount > amt) discount = amt;
}
const calc = { discount: fmt(discount), total: fmt(amt - discount), note };

const scopeBtn = st.fScope;
const create = (draft) => () => {
const code = st.fCode.trim().toUpperCase();
if (!/^[A-Z0-9_]{4,20}$/.test(code)) return this.setState({ fMsg: 'Mã gồm 4-20 ký tự: chữ hoa, số hoặc dấu gạch dưới.' });
if (CODES.some((x) => x.code === code)) return this.setState({ fMsg: 'Mã ' + code + ' đã tồn tại.' });
if (!v || (kindPct && v > 100)) return this.setState({ fMsg: 'Giá trị giảm không hợp lệ.' });
const d = /^(\d{4})-(\d{2})-(\d{2})$/.exec(st.fUntil || '');
const until = d ? d[3] + '/' + d[2] + '/' + d[1] : 'Không hết hạn';
const item = { code, kind: st.kind, val: v, min: minOrder, cap: kindPct ? cap : 0, scope: scopeBtn, used: 0, limit: num(st.fLimit), until, status: draft ? 'paused' : 'run' };
this._fail = false; this.saveShared('codes', CODES.concat([item]));
this.setState({ tick: this.state.tick + 1, fCode: '', fMsg: this._fail ? 'Không lưu được vào bộ nhớ trình duyệt.' : (draft ? 'Đã lưu nháp mã ' : 'Đã tạo mã ') + code + '.' });
};
const set = (k) => (e) => this.setState({ [k]: e.target.value });
return {
fCode: st.fCode, fScope: st.fScope, fUntil: st.fUntil, fLimit: st.fLimit, fMsg: st.fMsg, fMsgShow: st.fMsg !== '',
onFCode: (e) => this.setState({ fCode: e.target.value, fMsg: '' }), onFScope: (e) => this.setState({ fScope: e.target.value }),
onFUntil: (e) => this.setState({ fUntil: e.target.value }), onFLimit: (e) => this.setState({ fLimit: e.target.value }),
onRandom: () => this.setState({ fCode: 'SN' + Math.random().toString(36).slice(2, 8).toUpperCase(), fMsg: '' }),
onCreate: create(false), onDraft: create(true),
nav, tabs, rows, hub, calc,
kind: st.kind, val: st.val, cap: st.cap, min: st.min, order: st.order,
hasCap: kindPct,
valLabel: kindPct ? 'Giá trị (%)' : 'Giá trị (₫)',
onKind: set('kind'), onVal: set('val'), onCap: set('cap'), onMin: set('min'), onOrder: set('order'),
onStack: () => this.setState({ stack: !this.state.stack }),
stack: {
checked: st.stack ? 'true' : 'false',
label: st.stack ? 'Đang bật' : 'Đang tắt',
bg: st.stack ? '#0F1320' : 'transparent',
fg: st.stack ? ok : off
}
};
}
}

